#include <stdio.h>
#include <stdlib.h>
#include <string.h>
long long dmax(long long v){long long m=0;while(v){if(v%10>m)m=v%10;v/=10;}return m;}int main(void){int n,i;static long long a[500005];if(scanf("%d",&n)!=1)return 1;for(i=0;i<n;i++)scanf("%lld",&a[i]);long long s=0;int c=0;for(i=0;i<n;i++){long long x=a[i];if(dmax(x) % 2 != 0){s+=x;c++;}}printf("%lld\n",c?s/c:-1);return 0;}
